import test from 'node:test';
import assert from 'node:assert/strict';
import { createAgentActions, createEngineeringPackage, toSvg, verifyResult } from '../src/index.mjs';
import { fixture } from './helpers.mjs';
test('agent action snapshots and enforces the selected architectural revision', async () => { const p = fixture(), actions = createAgentActions({ getProject: () => p }); const s = await actions.snapshot(); const r = await actions.generate({ expectedArchitectureHash: s.architectureHash, disciplines: ['plumbing'] }); assert.equal(r.architectureHash, s.architectureHash); await assert.rejects(actions.generate({ expectedArchitectureHash: '0'.repeat(64) }), { code: 'ARCHITECTURE_REVISION_CONFLICT' }); });
test('agent render rereads services and rejects a stale calculation', async () => { const p = fixture(), actions = createAgentActions({ getProject: () => p }), s = await actions.snapshot(); const r = await actions.generate({ expectedArchitectureHash: s.architectureHash, disciplines: ['electrical'] }); p.services.electrical.loads[0].powerW++; await assert.rejects(actions.render({ expectedArchitectureHash: s.architectureHash, result: r, format: 'svg' }), { code: 'STALE_RESULT' }); });
test('a serialized unchanged result passes its independent result digest check', async () => { const r = await createEngineeringPackage(fixture(), { disciplines: ['plumbing'] }); assert.equal(await verifyResult(JSON.parse(JSON.stringify(r))), true); });
test('an undrawn floor is explicitly empty rather than an invalid or fabricated plan', async () => { const p = fixture(); p.architecture.levels.push({ id: 'L2', elevationM: 3.5, heightM: 3.2 }); const r = await createEngineeringPackage(p); const svg = await toSvg(p, r, { levelId: 'L2' }); assert.ok(svg.includes('NO_LEVEL_GEOMETRY')); assert.ok(!svg.includes('Infinity')); assert.ok(r.issues.some(i => i.code === 'LEVEL_ARCHITECTURE_MISSING')); });
